# Tools configuration for Atoma GitHub templates
#
# Every server named here must cover the union of `mcp_servers` across
# .github/atoma/agent-definitions/*.md. An agent naming a server that is absent
# here aborts before any MCP server starts ("Tool 'X' not found in tools file"),
# so removals must be checked against all three agents, not just the one in
# front of you. `agent-definitions.test.ts` enforces this.

filesystem:
  command: bun
  args: ["run", ".github/atoma/tools/scripts/mcp/filesystem.ts", "."]
  env: {}
  hooks:
    tool_denylist:
      - "filesystem__directory_tree"
      - "filesystem__search_files"

filesystem_readonly:
  command: bun
  args: ["run", ".github/atoma/tools/scripts/mcp/filesystem.ts", "."]
  env: {}
  hooks:
    tool_allowlist:
      - "filesystem_readonly__read_file"
      - "filesystem_readonly__read_multiple_files"
      - "filesystem_readonly__list_directory"
      - "filesystem_readonly__get_file_info"

shell:
  command: bun
  args: ["run", ".github/atoma/tools/scripts/mcp/shell.ts"]
  env: {}
  hooks:
    before_tool: ./scripts/hooks/shell_guard.ts

github:
  command: bun
  args: ["run", ".github/atoma/tools/scripts/mcp/github.ts"]
  env: {}
  hooks: {}

atoma:
  command: bun
  args: ["run", ".github/atoma/tools/scripts/mcp/atoma.ts"]
  env: {}
  hooks: {}


